# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GENİŞ AİLE BİREYLERİ VE İSİM TAMLAMASI (أَقارِبي)</text>\n  <rect x="35" y="55" width="200" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="135" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Baba Tarafı Akrabalar</text>\n  <text x="135" y="110" text-anchor="middle" font-size="12" fill="#334155">جَدّ (Dede) / جَدَّة (Nine)</text>\n  <text x="135" y="135" text-anchor="middle" font-size="12" fill="#334155">عَمّ (Amca) / عَمَّة (Hala)</text>\n  <text x="135" y="160" text-anchor="middle" font-size="12" fill="#334155">وَلَدُ الْعَمّ (Amca oğlu)</text>\n  <text x="135" y="185" text-anchor="middle" font-size="12" fill="#334155">بِنْتُ الْعَمَّة (Hala kızı)</text>\n  <text x="135" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">عَمّي (Amcam) • عَمَّتي (Halam)</text>\n  <rect x="250" y="55" width="200" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Anne Tarafı Akrabalar</text>\n  <text x="350" y="110" text-anchor="middle" font-size="12" fill="#334155">والِد (Baba) / والِدَة (Anne)</text>\n  <text x="350" y="135" text-anchor="middle" font-size="12" fill="#334155">خال (Dayı) / خالَة (Teyze)</text>\n  <text x="350" y="160" text-anchor="middle" font-size="12" fill="#334155">وَلَدُ الْخالَة (Teyze oğlu)</text>\n  <text x="350" y="185" text-anchor="middle" font-size="12" fill="#334155">بِنْتُ الْخال (Dayı kızı)</text>\n  <text x="350" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">خالي (Dayım) • خالَتي (Teyzem)</text>\n  <rect x="465" y="55" width="200" height="180" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="565" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Çocuklar ve Torunlar</text>\n  <text x="565" y="110" text-anchor="middle" font-size="12" fill="#334155">وَلَد (Oğul / Erkek çocuk)</text>\n  <text x="565" y="135" text-anchor="middle" font-size="12" fill="#334155">بِنْت (Kız çocuk)</text>\n  <text x="565" y="160" text-anchor="middle" font-size="12" fill="#334155">حَفيد (Erkek torun)</text>\n  <text x="565" y="185" text-anchor="middle" font-size="12" fill="#334155">حَفيدَة (Kız torun)</text>\n  <text x="565" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#ca8a04">رَبَّةُ الْبَيْت (Ev hanımı)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MESLEKLER VE NEREDE ÇALIŞIYOR? (أَيْنَ يَعْمَلُ / تَعْمَلُ؟)</text>\n  <rect x="40" y="55" width="300" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="190" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Meslek Eşleşmeleri (Eril / Dişil)</text>\n  <text x="190" y="108" text-anchor="middle" font-size="11.5" fill="#334155">مُعَلِّم / مُعَلِّمَة (Öğretmen) • مُمَرِّض / مُمَرِّضَة (Hemşire)</text>\n  <text x="190" y="133" text-anchor="middle" font-size="11.5" fill="#334155">سائِق / سائِقَة (Şoför) • بَيْطَرِيّ / بَيْطَرِيَّة (Veteriner)</text>\n  <text x="190" y="158" text-anchor="middle" font-size="11.5" fill="#334155">فَلّاح / فَلّاحَة (Çiftçi) • مُحامٍ / مُحامِيَة (Avukat)</text>\n  <text x="190" y="183" text-anchor="middle" font-size="11.5" fill="#334155">طَبّاخ / طَبّاخَة (Aşçı) • شُرْطِيّ / شُرْطِيَّة (Polis)</text>\n  <text x="190" y="210" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">ضابِط / ضابِطَة (Subay) • نَشيط / ماهِر (Çalışkan / Maharetli)</text>\n  <rect x="360" y="55" width="300" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="510" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Çalışma Yeri Diyalog Kalıpları</text>\n  <text x="510" y="110" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">أَيْنَ تَعْمَلُ الْمُعَلِّمَة؟ (Öğretmen nerede çalışır?)</text>\n  <text x="510" y="132" text-anchor="middle" font-size="11.5" fill="#334155">تَعْمَلُ الْمُعَلِّمَةُ في الْمَدْرَسَة. (Okulda çalışır.)</text>\n  <text x="510" y="160" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">أَيْنَ يَعْمَلُ الضّابِط؟ (Subay nerede çalışır?)</text>\n  <text x="510" y="182" text-anchor="middle" font-size="11.5" fill="#334155">يَعْمَلُ الضّابِطُ في الْعَمَل. (İş yerinde çalışır.)</text>\n  <text x="510" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">لا تَعْمَلُ الطَّبّاخَةُ في الصَّفّ (Aşçı sınıfta çalışmaz.)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">AİLE VE AKRABALIK DEĞERLERİ: HADİS VE VECİZ SÖZLER</text>\n  <rect x="40" y="55" width="620" height="85" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="350" y="82" text-anchor="middle" font-size="15" font-weight="bold" fill="#a16207">« خَيْرُكُمْ خَيْرُكُمْ لِأَهْلِهِ »</text>\n  <text x="350" y="106" text-anchor="middle" font-size="12" fill="#334155">"Sizin en hayırlınız, ailesine karşı en hayırlı (iyi ve merhametli) olanınızdır."</text>\n  <text x="350" y="126" text-anchor="middle" font-size="11" fill="#64748b">Aile bireylerine sevgi, saygı ve nezaketle davranmak İslam ahlakının temelidir.</text>\n  <rect x="40" y="152" width="620" height="85" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="350" y="179" text-anchor="middle" font-size="15" font-weight="bold" fill="#1d4ed8">« اَلْأَقْرَبُونَ أَوْلَى بِالْمَعْرُوفِ »</text>\n  <text x="350" y="203" text-anchor="middle" font-size="12" fill="#334155">"İyiliğe ve yardıma en layık olanlar, en yakın akrabalardır."</text>\n  <text x="350" y="223" text-anchor="middle" font-size="11" fill="#64748b">Sıla-i rahim (akraba ziyareti ve yardımlaşma) toplumsal dayanışmayı güçlendirir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
